// QUA 07 (P1) — Plano_de_Testes_QA_MatchWallet.md §13 (docs-test/areas/qua.md), parte observável
// pelo navegador: respostas e erros não vazam segredos nem detalhes internos.
//
// NÃO coberto: a trilha de auditoria (ator, data, entidade, versão). O backend não expõe log de
// auditoria por API e o acesso aos logs de homologação é externo ao Cypress — conferir à mão.

const SEGREDO = /senha|password|passwd|hash|secret|token|salt/i
const DETALHE_INTERNO =
  /\bstack\b|node_modules|\/src\/|\.ts:\d+|prisma|PrismaClient|SELECT\s|INSERT\s|at\s+\S+\s+\(/i

/** Procura chaves com nome de segredo em qualquer profundidade do JSON. */
function chavesSecretas(valor: unknown, caminho = ''): string[] {
  if (Array.isArray(valor)) {
    return valor.flatMap((v, i) => chavesSecretas(v, `${caminho}[${i}]`))
  }
  if (valor && typeof valor === 'object') {
    return Object.entries(valor).flatMap(([chave, v]) => [
      ...(SEGREDO.test(chave) ? [`${caminho}.${chave}`] : []),
      ...chavesSecretas(v, `${caminho}.${chave}`),
    ])
  }
  return []
}

function semVazamento(rotulo: string, body: unknown) {
  expect(chavesSecretas(body), `chaves sensíveis em ${rotulo}`).to.deep.eq([])
  expect(JSON.stringify(body), `detalhe interno em ${rotulo}`).not.to.match(DETALHE_INTERNO)
}

describe('Plano QA · Respostas sem vazamento de dados (QUA 07)', () => {
  it('QUA 07 · cadastro, login e /auth/me → nenhuma senha, hash ou token no corpo e cookie de sessão HttpOnly', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta).then(({ body }) => semVazamento('POST /auth/login', body))

      // O token de sessão não é legível por JavaScript.
      cy.getCookie('access_token').should('exist').and('have.property', 'httpOnly', true)

      cy.apiRequest({ method: 'GET', url: '/auth/me' }).then(({ body }) => {
        semVazamento('GET /auth/me', body)
        expect(JSON.stringify(body)).not.to.contain(conta.senha)
      })
    })
  })

  it('QUA 07 · admin lista usuários e histórico → corpo sem credenciais nem dados internos', () => {
    cy.loginReal('admin')
    cy.apiRequest<{ items: Array<{ id: string }> }>({
      method: 'GET',
      url: '/usuarios?pageSize=50',
    }).then(({ body }) => {
      semVazamento('GET /usuarios', body)
      const primeiro = body.items[0]
      if (primeiro) {
        cy.apiRequest({
          method: 'GET',
          url: `/usuarios/${primeiro.id}/historico-suitability`,
        }).then(({ body: historico }) =>
          semVazamento('GET /usuarios/:id/historico-suitability', historico),
        )
      }
    })
  })

  it('QUA 07 · erros 400, 401 e 404 → só código e mensagem, sem pilha, SQL ou caminhos internos', () => {
    cy.loginReal('cliente')

    const erros = [
      { rotulo: '404 UUID inexistente', url: '/carteiras/00000000-0000-4000-8000-000000000000' },
      { rotulo: '400 UUID malformado', url: '/carteiras/nao-e-uuid' },
      { rotulo: '404 rota inexistente', url: '/rota-que-nao-existe' },
      {
        rotulo: '400 consulta com aspas e SQL',
        url: `/carteiras?perfil=${encodeURIComponent("' OR 1=1; --")}`,
      },
    ]
    for (const { rotulo, url } of erros) {
      cy.apiRequest({ method: 'GET', url, failOnStatusCode: false }).then(({ status, body }) => {
        expect(status, rotulo).to.be.within(400, 499)
        semVazamento(rotulo, body)
      })
    }

    cy.clearCookies()
    cy.apiRequest({ method: 'GET', url: '/auth/me', failOnStatusCode: false }).then(
      ({ status, body }) => {
        expect(status).to.eq(401)
        semVazamento('401 sem sessão', body)
      },
    )
  })

  it('QUA 07 · login com e-mail inexistente e com senha errada → mesma resposta (não revela quais e-mails existem)', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      const tentar = (email: string) =>
        cy
          .apiRequest<{ error?: { code?: string; message?: string } }>({
            method: 'POST',
            url: '/auth/login',
            body: { email, senha: 'SenhaErrada@999' },
            failOnStatusCode: false,
          })
          .then(({ status, body }) => ({ status, erro: body.error }))

      tentar(conta.email).then((existente) => {
        tentar(`inexistente.${conta.email}`).then((inexistente) => {
          expect(existente.status).to.eq(inexistente.status)
          expect(existente.erro?.code).to.eq(inexistente.erro?.code)
          expect(existente.erro?.message).to.eq(inexistente.erro?.message)
          semVazamento('login inválido', existente.erro)
        })
      })
    })
  })
})

export {}
